INSERT INTO documents(id,title,source,body) VALUES('doc-policy-1','Giữ hàng khi đặt đơn','Sổ tay nhà sách Conan','Khi đặt đơn, hệ thống kiểm tra và giữ số lượng khả dụng theo từng tập. Nếu một tập hết hàng, cả đơn sẽ không được xác nhận.');
